content.css:
.sth{position:sticky;top:0;z-index:100;border-bottom:1px solid var(--color-border,#e5e5e5);font-family:var(--font-sans,Inter,ui-sans-serif,system-ui,sans-serif)}
/* The translucent blur lives on a pseudo-element: backdrop-filter on .sth itself would make the
   header the containing block for the fixed drawer and scrim, pinning them to the header box. */
.sth::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;background:color-mix(in srgb,var(--color-bg,#fff) 88%,transparent);-webkit-backdrop-filter:saturate(180%) blur(12px);backdrop-filter:saturate(180%) blur(12px)}
.sth-skip{position:absolute;inset-inline-start:-9999px;top:.5rem;padding:.5rem .9rem;background:var(--color-text,#1a1a1a);color:var(--color-bg,#fff);border-radius:.5rem;z-index:1}
.sth-skip:focus{inset-inline-start:.75rem}
.sth-inner{display:flex;align-items:center;gap:2rem;max-width:1180px;margin:0 auto;padding:0 1.5rem;height:68px}
.sth-logo,.sth-panel-logo{display:inline-flex;align-items:center;gap:.55rem;font-family:var(--font-heading,inherit);font-size:1.0625rem;font-weight:700;letter-spacing:-.02em;color:var(--color-text,#1a1a1a);text-decoration:none}
.sth-mark{display:block;width:28px;height:28px}
.sth-nav{display:flex;gap:1.75rem;font-size:.9375rem;margin-inline-start:auto}
.sth-nav a{position:relative;color:var(--color-text-secondary,#525252);text-decoration:none;padding-block:.35rem;transition:color 140ms ease}
.sth-nav a::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--color-brand,#e2603a);transform:scaleX(0);transform-origin:left;transition:transform 160ms ease}
.sth-nav a:hover{color:var(--color-text,#1a1a1a)}
.sth-nav a:hover::after{transform:scaleX(1)}
.sth-cta{font-size:.875rem;font-weight:600;line-height:1;white-space:nowrap;padding:.65rem 1.1rem;border-radius:calc(var(--radius,.75rem) * 1.2);background:var(--color-brand,#e2603a);color:var(--color-on-brand,#fff);text-decoration:none;transition:filter 140ms ease}
.sth-cta:hover{filter:brightness(1.06)}
.sth-check{display:none}
.sth-burger{display:none;flex-direction:column;justify-content:center;gap:4px;width:38px;height:38px;padding:9px;cursor:pointer}
.sth-burger span{display:block;height:2px;background:var(--color-text,#1a1a1a);border-radius:1px}
.sth-scrim{position:fixed;inset:0;background:rgba(0,0,0,.45);opacity:0;pointer-events:none;transition:opacity 140ms ease;z-index:205}
/* Closed drawer is display:none, not parked off-screen — a fixed element sitting outside the
   viewport still adds to the page's scrollable width, which scrolls the whole site sideways.
   Opening animates; closing snaps. */
.sth-panel{display:none;position:fixed;top:0;inset-inline-end:0;height:100dvh;width:min(320px,86vw);background:var(--color-bg,#fff);border-inline-start:1px solid var(--color-border,#e5e5e5);z-index:210;flex-direction:column;gap:1.5rem;padding:1.25rem;overflow-y:auto}
@keyframes sth-slide-in{from{transform:translateX(100%)}to{transform:none}}
.sth-check:checked ~ .sth-scrim{opacity:1;pointer-events:auto}
.sth-check:checked ~ .sth-panel{display:flex;animation:sth-slide-in 220ms ease}
.sth-panel-head{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--color-border,#e5e5e5);padding-bottom:.85rem}
.sth-close{font-size:1.75rem;line-height:1;color:var(--color-muted,#8b8b8b);cursor:pointer}
.sth-panel-nav{display:flex;flex-direction:column;gap:1.1rem;font-size:1.125rem}
.sth-panel-nav a{color:var(--color-text,#1a1a1a);text-decoration:none}
.sth-cta--panel{margin-top:auto;text-align:center;padding:.85rem 1.1rem}
@media (max-width:940px){.sth-nav{display:none}.sth-cta:not(.sth-cta--panel){display:none}.sth-burger{display:flex;margin-inline-start:auto}}
@media (prefers-reduced-motion:reduce){.sth-scrim,.sth-nav a::after{transition:none}.sth-check:checked ~ .sth-panel{animation:none}}
